/* ============================================================
   LEARNING ENGINE
   Ported from the tested prototype. Three evidence-led behaviours:
   1. Spacing by ENCOUNTER, not by day — children play unpredictably.
   2. A word keeps resurfacing until it has been met enough times to
      consolidate, even when answered correctly: the benefit of repetition
      is largest across the first several encounters.
   3. Distractors in listening rounds are words the child ALREADY knows
      (mutual exclusivity), which tested as the strongest mechanism for
      four-year-olds learning new words.
   ============================================================ */

const CONSOLIDATE_AT = 12;

function recordAnswer(bank, key, correct) {
  const r = bank[key] || { seen: 0, ok: 0, lvl: 0, last: 0 };
  r.seen += 1;
  r.last = Date.now();
  if (correct) { r.ok += 1; r.lvl = Math.min(5, r.lvl + 1); }
  else { r.lvl = Math.max(0, r.lvl - 1); }
  bank[key] = r;
  return r;
}

const isKnown = (bank, key) => !!(bank[key] && bank[key].ok > 0);
const isConsolidated = (bank, key) => {
  const r = bank[key];
  return !!(r && r.seen >= CONSOLIDATE_AT && r.lvl >= 4);
};

function weightOf(bank, key) {
  const r = bank[key];
  if (!r || !r.seen) return 14;                       // never seen — top priority
  const needsMore = r.seen < CONSOLIDATE_AT ? (CONSOLIDATE_AT - r.seen) * 0.4 : 0;
  return Math.max(1, (7 - r.lvl) + needsMore);
}

function pickWeighted(bank, words, n) {
  const pool = words.map((w) => ({ w, k: weightOf(bank, w.key) }));
  const out = [];
  while (out.length < n && pool.length) {
    const total = pool.reduce((a, b) => a + b.k, 0);
    let r = Math.random() * total, i = 0;
    while (r > 0 && i < pool.length) { r -= pool[i].k; if (r > 0) i++; }
    out.push(pool.splice(Math.min(i, pool.length - 1), 1)[0].w);
  }
  return out;
}

function countKnown(bank, categories) {
  let have = 0, all = 0, solid = 0;
  categories.forEach((c) => c.words.forEach((w) => {
    all += 1;
    if (isKnown(bank, w.key)) have += 1;
    if (isConsolidated(bank, w.key)) solid += 1;
  }));
  return { have, all, solid };
}

/* ---------- levels unlock GAMES, not abstract badges ---------- */
const LEVELS = [
  { at: 0,  game: 'match',   icon: '🃏', name: 'Matching' },
  { at: 6,  game: 'choose',  icon: '👂', name: 'Listen & Find' },
  { at: 14, game: 'missing', icon: '🫥', name: "What's Missing?" },
  { at: 20, game: 'say',     icon: '🎤', name: 'Say It!' },
  { at: 24, game: 'tutor',   icon: '💬', name: 'Talk with your buddy' },
  { at: 32, game: 'odd',     icon: '🧐', name: 'Odd One Out' },
  { at: 44, game: 'big',     icon: '🎴', name: 'Big Match' },
];
function levelFor(known) {
  let idx = 0;
  LEVELS.forEach((l, i) => { if (known >= l.at) idx = i; });
  const next = LEVELS[idx + 1] || null;
  return { idx, level: idx + 1, next, toNext: next ? Math.max(0, next.at - known) : 0 };
}
const unlocked = (known) => LEVELS.slice(0, levelFor(known).idx + 1).map((l) => l.game);

const shuffle = (a) => {
  const b = a.slice();
  for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]]; }
  return b;
};

/* ---------- build one short session ---------- */
function buildSession(bank, categories, topicIdx) {
  const cat = categories[topicIdx % categories.length];
  const fresh    = cat.words.filter((w) => !isKnown(bank, w.key));
  const familiar = cat.words.filter((w) =>  isKnown(bank, w.key));

  const NEW_CAP = 3;
  const newWords = pickWeighted(bank, fresh.length ? fresh : cat.words,
                                Math.min(NEW_CAP, (fresh.length || cat.words.length)));
  const review = familiar.length ? pickWeighted(bank, familiar, Math.min(3, familiar.length)) : [];

  const pool = newWords.concat(review);
  while (pool.length < 4) {
    const extra = cat.words.filter((w) => pool.indexOf(w) < 0);
    if (!extra.length) break;
    pool.push(extra[Math.floor(Math.random() * extra.length)]);
  }

  const known = countKnown(bank, categories).have;
  const open  = unlocked(known);
  const lvl   = levelFor(known);
  const optionCount = lvl.level >= 4 ? 3 : 2;

  const chooseRound = (target) => {
    let distract = (familiar.length >= optionCount ? familiar : cat.words)
      .filter((w) => w.key !== target.key);
    const seen = {};
    distract = distract.filter((w) => (seen[w.key] ? false : (seen[w.key] = 1)));
    return {
      t: 'choose',
      target,
      pool: [target].concat(shuffle(distract).slice(0, optionCount)),
      me: familiar.length >= optionCount,
    };
  };

  const a = newWords.slice(0, 2);
  const b = newWords.slice(2).concat(review).slice(0, 2);
  const rounds = [];

  rounds.push({ t: 'learn', words: a.length ? a : pool.slice(0, 2) });
  rounds.push({ t: 'match', words: pool.slice(0, 3) });
  if (open.indexOf('choose') >= 0) rounds.push(chooseRound(a[0] || pool[0]));

  if (b.length) rounds.push({ t: 'learn', words: b });
  rounds.push({ t: 'match', words: pool.slice(Math.max(0, pool.length - 3)) });
  if (open.indexOf('choose') >= 0) rounds.push(chooseRound(b[0] || pool[1] || pool[0]));

  if (open.indexOf('missing') >= 0 && pool.length >= 3)
    rounds.push({ t: 'missing', words: shuffle(pool).slice(0, 3) });
  if (open.indexOf('tutor') >= 0 && pool.length >= 2)
    rounds.push({ t: 'tutor', words: shuffle(pool).slice(0, 3) });
  else if (open.indexOf('say') >= 0 && pool.length)
    rounds.push({ t: 'say', w: newWords[0] || pool[0] });
  if (open.indexOf('odd') >= 0) {
    const others = categories.filter((c) => c.id !== cat.id);
    const oc = others[Math.floor(Math.random() * others.length)];
    if (oc) {
      const pair = shuffle(pool).slice(0, 2);
      const odd = oc.words[Math.floor(Math.random() * oc.words.length)];
      if (pair.length === 2) rounds.push({ t: 'odd', pair, odd });
    }
  }
  if (open.indexOf('choose') >= 0)
    rounds.push(chooseRound(pool[pool.length - 1] || pool[0]));

  rounds.push({ t: 'match', words: pool.slice(0, open.indexOf('big') >= 0 ? 5 : 4) });
  rounds.push({ t: 'finish', cat });

  return { cat, pool, rounds, i: 0, earned: [] };
}



/* ============================================================
   TUTOR — a short spoken exchange with the character.

   Deliberately built WITHOUT a generative model and WITHOUT sending audio
   anywhere. iOS can transcribe speech on-device, so the child's voice never
   leaves the phone: no third-party terms to breach, no biometric data
   transmitted, nothing to obtain consent for.

   The "conversation" is a small scripted state machine with varied, warm
   responses. For a child of this age that is also better teaching than open
   conversation — they do not yet have the vocabulary to converse, so the
   value is in being asked, trying, and being encouraged.
   ============================================================ */

/* every reply exists in several forms so it never sounds mechanical */
const TUTOR_LINES = {
  ask:    ["Can you say it?", "Your turn!", "Now you try!", "What is it?"],
  great:  ["Perfect!", "That's it!", "Wonderful!", "You said it!"],
  close:  ["So close!", "Nearly!", "Good try — again?", "Almost!"],
  quiet:  ["I didn't hear you.", "Can you say it louder?", "Try once more?"],
  cheer:  ["You're getting good at this!", "Well done!", "Brilliant!"],
};
const pick = (a) => a[Math.floor(Math.random() * a.length)];

/* forgiving comparison — a small child's pronunciation of a foreign word will
   never match cleanly, so this is deliberately generous */
function tidy(t) {
  return (t || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, '').trim();
}
function closeness(heard, target) {
  const a = tidy(heard), b = tidy(target);
  if (!a || !b) return 0;
  if (a === b) return 1;
  if (a.indexOf(b) >= 0 || b.indexOf(a) >= 0) return 0.9;
  const m = {};
  for (const c of a) m[c] = (m[c] || 0) + 1;
  let hit = 0;
  for (const c of b) if (m[c] > 0) { m[c]--; hit++; }
  const overlap = hit / Math.max(a.length, b.length);
  const lenRatio = Math.min(a.length, b.length) / Math.max(a.length, b.length);
  return overlap * lenRatio;
}

/* ---------- the tutor round ---------- */
function TutorRound({ round, pack, theme, together, clips, onDone, onEarn, mark, sfx, say, speakIt }) {
  const T = theme;
  const words = round.words.slice(0, 3);
  const [turn, setTurn] = useState(0);          // which word we're on
  const [phase, setPhase] = useState('intro');  // intro | asking | listening | reply | done
  const [line, setLine] = useState('');
  const [heard, setHeard] = useState('');
  const [tries, setTries] = useState(0);
  const [canListen, setCanListen] = useState(false);
  const mounted = useRef(true);

  const word = words[turn];
  const targetText = () => strip(word.w, pack.articles);

  useEffect(() => () => { mounted.current = false; try { if (SR) SR.stop(); } catch (e) {} }, []);

  /* is on-device recognition usable? if not, the round still works — the child
     just taps to say they said it, and nothing is lost */
  useEffect(() => {
    (async () => {
      if (!SR) { setCanListen(false); return; }        // Expo Go: no recognition
      try {
        const res = await SR.requestPermissionsAsync();
        setCanListen(!!(res && res.granted));
      } catch (e) { setCanListen(false); }
    })();
  }, []);

  /* character speaks, then invites the child */
  const askNow = () => {
    setPhase('asking');
    setLine(pick(TUTOR_LINES.ask));
    say(word);                                   // hear the word first
    setTimeout(() => { if (mounted.current) setPhase('ready'); }, 1400);
  };
  useEffect(() => { const t = setTimeout(askNow, 700); return () => clearTimeout(t); }, [turn]);

  const listen = async () => {
    if (phase === 'listening') { try { if (SR) SR.stop(); } catch (e) {} return; }
    if (!canListen) { succeed(false); return; }   // no recognition: reward the attempt
    setHeard('');
    setPhase('listening');
    setLine('');
    try {
      if (!SR) { succeed(false); return; }
      SR.start({
        lang: pack.locale,
        interimResults: false,
        maxAlternatives: 3,
        requiresOnDeviceRecognition: true,       // audio never leaves the device
        continuous: false,
      });
    } catch (e) { succeed(false); }
  };

  /* results arrive through the module's events */
  useSpeechRecognitionEvent('result', (e) => {
    if (!mounted.current) return;
    const alts = (e && e.results ? e.results : []).map(r => r.transcript).filter(Boolean);
    const best = alts.reduce((s, t) => Math.max(s, closeness(t, targetText())), 0);
    setHeard(alts[0] || '');
    judge(best);
  });
  useSpeechRecognitionEvent('end', () => {
    if (!mounted.current) return;
    if (phase === 'listening') judge(-1);         // heard nothing at all
  });
  useSpeechRecognitionEvent('error', () => { if (mounted.current) judge(-1); });

  const judge = (score) => {
    if (score >= 0.55) { succeed(true); return; }
    const t = tries + 1;
    setTries(t);
    if (score < 0) { setLine(pick(TUTOR_LINES.quiet)); }
    else { setLine(pick(TUTOR_LINES.close)); }
    setPhase('reply');
    speakIt(score < 0 ? pick(TUTOR_LINES.quiet) : pick(TUTOR_LINES.close), { rate: 0.9 });
    /* after two goes the character simply says it again and moves on — a small
       child must never get stuck or feel they have failed */
    setTimeout(() => {
      if (!mounted.current) return;
      if (t >= 2) { succeed(false); }
      else { say(word); setTimeout(() => mounted.current && setPhase('ready'), 1200); }
    }, 1500);
  };

  const succeed = (matched) => {
    setPhase('reply');
    setLine(matched ? pick(TUTOR_LINES.great) : pick(TUTOR_LINES.cheer));
    const reply = matched ? pick(TUTOR_LINES.great) : pick(TUTOR_LINES.cheer);
    sfx('correct');
    setTimeout(() => { if (mounted.current) speakIt(reply, { rate: 0.95, pitch: 1.15 }); }, 560);
    mark(word.key, true);
    onEarn(word);
    setTries(0);
    setTimeout(() => {
      if (!mounted.current) return;
      if (turn + 1 >= words.length) { sfx('sticker'); onDone(); }
      else { setTurn(turn + 1); setPhase('intro'); setLine(''); }
    }, 1600);
  };

  const S2 = mk(T);
  const bubble = line || (phase === 'listening' ? '…' : '');

  return (
    <>
      {together ? (
        <View style={S2.coach}>
          <Text style={S2.coachTxt}>
            👋  Sit with them and say it together — {targetText()}. Any attempt counts.
          </Text>
        </View>
      ) : null}

      <Text style={{ fontSize: 74 }}>{T.hero}</Text>
      {bubble ? (
        <View style={S2.bubble}><Text style={S2.bubbleTxt}>{bubble}</Text></View>
      ) : null}

      <View style={[S2.big, { marginTop: 14 }]}>
        <Art w={word} size={92} />
      </View>

      <Pressable
        style={[S2.micBig, phase === 'listening' && { backgroundColor: T.mint }]}
        onPress={listen}
        disabled={phase === 'asking' || phase === 'reply'}
      >
        <Text style={{ fontSize: 40 }}>{phase === 'listening' ? '👂' : canListen ? '🎤' : '👏'}</Text>
      </Pressable>

      <Pressable style={S2.onward} onPress={() => succeed(false)}>
        <Text style={S2.onwardTxt}>we said it! →</Text>
      </Pressable>

      <View style={{ flexDirection: 'row', gap: 6, marginTop: 14 }}>
        {words.map((w, i) => (
          <View key={w.key} style={{
            width: 9, height: 9, borderRadius: 5,
            backgroundColor: i < turn ? T.sun : i === turn ? '#fff' : 'rgba(255,255,255,0.25)',
          }} />
        ))}
      </View>
    </>
  );
}

/* ================= APP ================= */
const KID_ART = ['🐢','🐰','🦊','🐸','🐥','🐨'];
const strip = (w, articles) => {
  let s = w;
  (articles||[]).forEach(a => { if (s.toLowerCase().startsWith(a.toLowerCase())) s = s.slice(a.length); });
  return s.trim();
};
const Art = ({ w, size }) => {
  if (w.hex) return <View style={{ width:size*0.8, height:size*0.8, borderRadius:size, backgroundColor:w.hex, borderWidth:2, borderColor:'rgba(0,0,0,0.15)' }} />;
  if (w.digit) return <Text style={{ fontSize:size, fontWeight:'900', color:'#16233F' }}>{w.digit}</Text>;
  return <Text style={{ fontSize:size }}>{w.emo || '❓'}</Text>;
};

export default function App() {
  const [ready, setReady] = useState(false);
  const [screen, setScreen] = useState('home');
  const [lang, setLang] = useState('it');
  const [tkey, setTkey] = useState('jungle');
  const [together, setTogether] = useState(false);
  const [kids, setKids] = useState({ list:[{id:'k1',art:'🐢'}], cur:'k1' });
  const [learn, setLearn] = useState({});
  const [meta, setMeta] = useState({});
  const [clips, setClips] = useState({});
  const [session, setSession] = useState(null);
  const [unlockCard, setUnlockCard] = useState(null);
  const [, force] = useState(0);
  const players = useRef({});
  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
  const [recOn, setRecOn] = useState(false);
  const [voices, setVoices] = useState([]);
  const [learnIdx, setLearnIdx] = useState(0);

  /* ---------- boot: audio + saved data ---------- */
  useEffect(() => {
    (async () => {
      try {
        // Sound plays even with the phone on silent — the whole reason this is native.
        await setAudioModeAsync({ playsInSilentMode: true, allowsRecording: false });
        for (const k of Object.keys(SFX)) {
          const p = FileSystem.cacheDirectory + k + '.m4a';
          await FileSystem.writeAsStringAsync(p, SFX[k], { encoding: 'base64' });
          players.current[k] = createAudioPlayer({ uri: p });
        }
      } catch (e) {}
      try { const vs = await Speech.getAvailableVoicesAsync(); setVoices(vs || []); } catch (e) {}
      try {
        const raw = await AsyncStorage.multiGet(['ws.learn','ws.meta','ws.kids','ws.clips']);
        const o = {}; raw.forEach(([k,v]) => { try { o[k] = v ? JSON.parse(v) : null; } catch(e){} });
        if (o['ws.learn']) setLearn(o['ws.learn']);
        if (o['ws.clips']) setClips(o['ws.clips']);
        if (o['ws.kids'])  setKids(o['ws.kids']);
        const m = o['ws.meta'] || {}; setMeta(m);
        if (m.theme) setTkey(m.theme);
        if (m.lang) setLang(m.lang);
      } catch (e) {}
      setReady(true);
    })();
  }, []);

  /* ---------- learn round: advances on a timer ----------
     Tapping the picture only REPEATS the word — it must never skip ahead,
     because small children press repeatedly. Moving on happens on a timer,
     so mashing the screen is harmless. */
  const roundNow = session ? session.rounds[session.i] : null;
  useEffect(() => { setLearnIdx(0); }, [session ? session.i : -1]);
  useEffect(() => {
    if (!session || !roundNow || roundNow.t !== 'learn') return;
    const w = roundNow.words[learnIdx];
    if (!w) return;
    const t1 = setTimeout(() => say(w), 260);
    recordAnswer(bank(), w.key, true);
    const t2 = setTimeout(() => {
      if (learnIdx + 1 >= roundNow.words.length) nextRound();
      else setLearnIdx(learnIdx + 1);
    }, 2800);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, [session ? session.i : -1, learnIdx]);

  const pack = PACKS.find(p => p.code === lang) || PACKS[0];
  const T = themeOf(tkey);
  const kkey = () => kids.cur + '/' + lang;
  const bank = () => { if (!learn[kkey()]) learn[kkey()] = {}; return learn[kkey()]; };
  const save = (k, v) => AsyncStorage.setItem(k, JSON.stringify(v)).catch(()=>{});
  const saveLearn = () => save('ws.learn', learn);
  const setM = (m) => { setMeta(m); save('ws.meta', m); };

  /* 'jingle' and 'unlock' are long musical pieces that talked over the voice,
     so they are no longer played. The files stay bundled in case a shorter
     version is wanted later. */
  const MUSIC = ['jingle', 'unlock'];
  const sfx = (n) => {
    if (MUSIC.indexOf(n) >= 0) return;
    const p = players.current[n]; if (!p) return;
    try { p.seekTo(0); p.play(); } catch(e){}
  };
  /* Voice quality matters: iOS returns the low-quality "compact" voice first,
     so score every candidate and prefer Enhanced/Premium ones. If the user has
     downloaded a better voice in iOS Settings, this picks it up automatically. */
  const voiceScore = (v, locale) => {
    if (!v || !v.language) return -1;
    const base = (locale || '').split('-')[0];
    const vl = v.language.replace('_', '-');
    let s = 0;
    if (vl === locale) s += 40;
    else if (vl.split('-')[0] === base) s += 20;
    else return -1;
    const q = String(v.quality || '').toLowerCase();
    if (q.indexOf('enhanced') >= 0 || q.indexOf('premium') >= 0) s += 30;
    const n = String(v.name || '').toLowerCase();
    if (/premium|enhanced|neural|siri/.test(n)) s += 12;
    if (/compact|eloquence/.test(n)) s -= 25;
    return s;
  };
  const voicesFor = (locale) => voices.filter(v => voiceScore(v, locale) > 0)
                                      .sort((a, b) => voiceScore(b, locale) - voiceScore(a, locale));
  const bestVoice = (locale) => {
    if (meta.voice) { const c = voices.find(v => v.identifier === meta.voice); if (c) return c; }
    let best = null, bs = -1;
    voices.forEach(v => { const s = voiceScore(v, locale); if (s > bs) { bs = s; best = v; } });
    return bs > 0 ? best : null;
  };
  const speakIt = (text, opts) => {
    try {
      Speech.stop();
      const v = bestVoice(pack.locale);
      const o = { language: pack.locale, rate: (opts && opts.rate) || 0.85, pitch: (opts && opts.pitch) || 1.05 };
      if (v) o.voice = v.identifier;
      Speech.speak(text, o);
    } catch (e) {}
  };
  const say = (w) => {
    const uri = clips[pack.code + ':' + w.key];
    if (uri) { try { const p = createAudioPlayer({ uri }); p.play(); return; } catch(e){} }
    speakIt(strip(w.w, pack.articles));
  };
  const praise = () => {
    const l = pack.praise || ['Bravo'];
    speakIt(l[Math.floor(Math.random()*l.length)].replace(/[!¡?¿.]/g,''), { rate: 0.95, pitch: 1.2 });
  };

  /* A sound and the voice must never overlap — a child cannot hear the word
     through a tune. The long musical cues are gone; the short chimes that
     remain finish before anything is spoken. */
  const CHIME_MS = { correct: 560, nope: 470, sticker: 900, tap: 130, twinkle: 440 };
  const sfxThen = (name, fn) => { sfx(name); setTimeout(fn, CHIME_MS[name] || 400); };

  const counts = countKnown(bank(), pack.categories);
  const lv = levelFor(counts.have);

  /* ---------- toddler-proofing ---------- */
  const lockUntil = useRef(0), advancing = useRef(false);
  const locked = () => Date.now() < lockUntil.current || advancing.current;
  const lockFor = (ms) => { lockUntil.current = Math.max(lockUntil.current, Date.now()+ms); };

  const start = () => { sfx('tap'); const s = buildSession(bank(), pack.categories, meta.topic||0); s.earned=[]; setSession(s); setScreen('play'); };
  const nextRound = () => {
    if (!session || advancing.current) return;
    if (session.i >= session.rounds.length-1) return;
    advancing.current = true; lockFor(420);
    setSession({ ...session, i: session.i+1 });
    setTimeout(()=>{ advancing.current = false; }, 420);
  };
  const earn = (w) => { if (session && !session.earned.find(x=>x.key===w.key)) session.earned.push(w); };
  const finish = () => {
    const m = { ...meta, topic: ((meta.topic||0)+1) % pack.categories.length, sessions: (meta.sessions||0)+1 };
    const seen = m.seenLevel || {}; const before = seen[kkey()] || 0;
    const now = levelFor(countKnown(bank(), pack.categories).have).idx;
    if (now > before) { seen[kkey()] = now; setUnlockCard(LEVELS[now]); sfx('unlock'); }
    m.seenLevel = seen; setM(m); saveLearn();
  };

  if (!ready) return (
    <View style={{flex:1,backgroundColor:'#1B2A5B',alignItems:'center',justifyContent:'center'}}>
      <Text style={{fontSize:88}}>🦁</Text>
      <Text style={{color:'#fff',fontSize:26,fontWeight:'900',marginTop:8}}>Word Safari</Text>
    </View>
  );

  const S = mk(T);
  const Coach = ({t}) => !together ? null : <View style={S.coach}><Text style={S.coachTxt}>👋  {t}</Text></View>;
  const Unlock = () => !unlockCard ? null : (
    <View style={S.overlay}><View style={[S.uCard,{backgroundColor:T.mid}]}>
      <Text style={{fontSize:80}}>{unlockCard.icon}</Text>
      <Text style={[S.uNew,{color:T.sun}]}>NEW GAME!</Text>
      <Text style={S.uName}>{unlockCard.name}</Text>
      <Pressable style={[S.rBtn,{backgroundColor:T.sun,marginTop:20}]} onPress={()=>setUnlockCard(null)}><Text style={{fontSize:30}}>✓</Text></Pressable>
    </View></View>
  );

  /* ================= PLAY ================= */
  if (screen === 'play' && session) {
    const r = session.rounds[session.i];
    let body = null;

    if (r.t === 'learn') {
      const w = r.words[Math.min(learnIdx, r.words.length - 1)];
      body = (<>
        <Coach t={'Point and ask: "Can you say ' + strip(w.w, pack.articles) + '?"'} />
        <Pressable style={S.big} onPress={()=>{ if(!locked()){ say(w); } }}><Art w={w} size={116}/></Pressable>
        <Text style={S.hint}>👆 tap to hear</Text>
        <View style={{flexDirection:'row',gap:6,marginTop:14}}>
          {r.words.map((x,i)=>(
            <View key={x.key} style={{width:9,height:9,borderRadius:5,
              backgroundColor: i < learnIdx ? T.sun : i === learnIdx ? '#fff' : 'rgba(255,255,255,0.25)'}}/>
          ))}
        </View>
      </>);
    }

    if (r.t === 'match') {
      if (!session.m || session.m.key !== session.i) {
        session.m = { key:session.i, deck: shuffle(r.words.flatMap((w,i)=>[{i,w},{i,w}])), up:[], got:[], lock:false, total:r.words.length };
      }
      const m = session.m;
      body = (<>
        <Coach t="Name each picture as they turn it over." />
        <View style={S.grid}>
          {m.deck.map((d,i)=>{
            const up = m.up.indexOf(i)>=0, got = m.got.indexOf(d.i)>=0;
            return (
              <Pressable key={i} style={[S.mC, got && {backgroundColor:T.mint}]} onPress={()=>{
                if (m.lock || locked() || m.up.length>=2 || m.up.indexOf(i)>=0 || got) return;
                m.up.push(i); say(d.w); sfx('tap'); force(x=>x+1);
                if (m.up.length===2) {
                  m.lock = true; const [x,y] = m.up;
                  if (m.deck[x].i === m.deck[y].i) setTimeout(()=>{
                    m.got.push(m.deck[x].i); m.up=[]; m.lock=false;
                    sfxThen('correct', praise); recordAnswer(bank(), m.deck[x].w.key, true); earn(m.deck[x].w); force(x=>x+1);
                    if (m.got.length>=m.total){ m.lock=true; setTimeout(()=>{ sfx('sticker'); nextRound(); },650); }
                  },260);
                  else setTimeout(()=>{ sfx('nope'); m.up=[]; m.lock=false; force(x=>x+1); },750);
                }
              }}>
                {up||got ? <View style={S.mF}><Art w={d.w} size={38}/></View> : <Text style={{fontSize:32,opacity:0.6}}>{T.back}</Text>}
              </Pressable>
            );
          })}
        </View>
      </>);
    }

    if (r.t === 'choose' || r.t === 'odd' || r.t === 'missing') {
      const target = r.t==='choose' ? r.target : r.t==='odd' ? r.odd : (session.gone || (session.gone = r.words[Math.floor(Math.random()*r.words.length)]));
      const list = r.t==='choose' ? r.pool : r.t==='odd' ? r.pair.concat([r.odd]) : r.words;
      body = (<>
        <Coach t={r.t==='choose' ? 'Ask: "Where is the ' + strip(target.w, pack.articles) + '?"' : r.t==='odd' ? 'Ask: "Which one is different?"' : 'Ask: "Which one has gone?"'} />
        {r.t==='choose' && <Pressable style={S.ear} onPress={()=>{ if(!locked()) say(target); }}><Text style={{fontSize:42}}>🔊</Text></Pressable>}
        <View style={S.row}>
          {shuffle(list).map(o=>{
            const wrong = (session.wrong||[]).indexOf(o.key)>=0;
            return (
              <Pressable key={o.key} style={[S.opt, wrong && {opacity:0.35}]} onPress={()=>{
                if (locked()) return;
                if (o.key === target.key) {
                  lockFor(900); sfxThen('correct', praise);
                  recordAnswer(bank(), target.key, true); earn(o);
                  session.wrong = []; session.gone = null;
                  setTimeout(()=>nextRound(), 950);
                } else {
                  sfx('nope'); session.wrong = (session.wrong||[]).concat([o.key]);
                  recordAnswer(bank(), target.key, false); force(x=>x+1);
                  if (session.wrong.length>=2) setTimeout(()=>say(target), 400);
                }
              }}><Art w={o} size={54}/></Pressable>
            );
          })}
        </View>
      </>);
    }

    if (r.t === 'tutor') {
      body = (
        <TutorRound
          round={r} pack={pack} theme={T} together={together} clips={clips}
          sfx={sfx} say={say} speakIt={speakIt}
          mark={(k, ok) => recordAnswer(bank(), k, ok)}
          onEarn={earn}
          onDone={() => nextRound()}
        />
      );
    }

    if (r.t === 'say') {
      const ph = ({it:'Questo è ',es:'Esto es ',fr:"C'est ",en:'This is '}[pack.code]||'') + r.w.w;
      body = (<>
        <Coach t={'Say it together: ' + ph} />
        <View style={S.big}><Art w={r.w} size={96}/></View>
        <Pressable style={S.phrase} onPress={()=>speakIt(ph, { rate: 0.8 })}>
          <Text style={S.phraseTxt}>🔊  {ph}</Text></Pressable>
        <Pressable style={S.onward} onPress={()=>{ if(!locked()){ sfxThen('correct', praise); recordAnswer(bank(), r.w.key, true); earn(r.w); setTimeout(nextRound, 700); } }}>
          <Text style={S.onwardTxt}>we said it! →</Text></Pressable>
      </>);
    }

    if (r.t === 'finish') {
      body = (<>
        <Text style={{fontSize:104}}>{T.hero}</Text>
        <View style={S.row}>{session.earned.slice(0,4).map(w=><View key={w.key} style={[S.opt,{padding:12}]}><Art w={w} size={34}/></View>)}</View>
        <View style={{flexDirection:'row',gap:16,marginTop:26}}>
          <Pressable style={[S.rBtn,{backgroundColor:T.sun}]} onPress={()=>{ const s=buildSession(bank(),pack.categories,meta.topic||0); s.earned=[]; setSession(s); }}><Text style={{fontSize:32}}>▶</Text></Pressable>
          <Pressable style={S.rBtn} onPress={()=>{ saveLearn(); setSession(null); setScreen('home'); }}><Text style={{fontSize:30}}>🏠</Text></Pressable>
        </View>
      </>);
    }

    return (
      <SafeAreaView style={[S.wrap]}>
        <StatusBar barStyle="light-content"/>
        <View style={S.top}>
          <Pressable style={S.icon} onPress={()=>{ saveLearn(); setSession(null); setScreen('home'); }}><Text style={{fontSize:19}}>✕</Text></Pressable>
          <View style={S.pips}>{session.rounds.map((x,i)=><View key={i} style={[S.pip, i<session.i&&{backgroundColor:T.sun}, i===session.i&&{backgroundColor:'#fff'}]}/>)}</View>
        </View>
        <View style={S.stage}>{body}</View>
        <Unlock/>
      </SafeAreaView>
    );
  }

  /* ================= HOME ================= */
  if (screen === 'home') return (
    <SafeAreaView style={S.wrap}><StatusBar barStyle="light-content"/>
      <View style={S.top}>
        <Pressable style={S.kid} onPress={()=>{sfx('tap');setScreen('kids');}}><Text style={{fontSize:22}}>{(kids.list.find(k=>k.id===kids.cur)||kids.list[0]).art}</Text></Pressable>
        <View style={[S.chip,{backgroundColor:T.sun}]}><Text style={S.chipD}>⭐ {counts.have}</Text></View>
        <View style={S.chip}><Text style={S.chipT}>{LEVELS[lv.idx].icon} Lv {lv.level}</Text></View>
        <View style={{flex:1}}/>
        <Pressable style={S.icon} onPress={()=>{sfx('tap');setScreen('collection');}}><Text style={{fontSize:19}}>📖</Text></Pressable>
        <Pressable style={S.icon} onPress={()=>{sfx('tap');setScreen('parent');}}><Text style={{fontSize:19}}>⚙️</Text></Pressable>
      </View>
      <View style={S.center}>
        <Text style={{fontSize:96}}>{T.hero}</Text>
        <Text style={S.title}>Word Safari</Text>
        <View style={S.langWrap}>
          {PACKS.map(p=>(
            <Pressable key={p.code} style={[S.langC, p.code===lang&&{backgroundColor:'#fff'}]} onPress={()=>{sfx('tap');setLang(p.code);setM({...meta,lang:p.code});}}>
              <Text style={{fontSize:19}}>{p.flag}</Text>
              <Text style={[S.langT, p.code===lang&&{color:'#16233F'}]}>{p.name}</Text>
            </Pressable>
          ))}
        </View>
        <View style={S.themeRow}>
          {Object.keys(THEMES).map(k=>(
            <Pressable key={k} style={[S.tDot, k===tkey&&{backgroundColor:'#fff'}]} onPress={()=>{sfx('tap');setTkey(k);setM({...meta,theme:k});}}>
              <Text style={{fontSize:23}}>{THEMES[k].icon}</Text></Pressable>
          ))}
        </View>
        <Pressable style={[S.play,{backgroundColor:T.sun}]} onPress={start}><Text style={S.playT}>PLAY</Text></Pressable>
      </View>
      <Pressable style={[S.ghost, together&&{backgroundColor:T.mint}]} onPress={()=>{sfx('tap');setTogether(!together);}}>
        <Text style={[S.ghostT, together&&{color:'#16233F'}]}>{together?'👨‍👧 Playing together':'🧒 Play together'}</Text></Pressable>
      <Unlock/>
    </SafeAreaView>
  );

  /* ================= KIDS ================= */
  if (screen === 'kids') return (
    <SafeAreaView style={S.wrap}>
      <View style={S.head}><Pressable style={S.icon} onPress={()=>setScreen('home')}><Text style={{fontSize:19}}>←</Text></Pressable>
        <Text style={S.headT}>Who is playing?</Text></View>
      <ScrollView contentContainerStyle={{padding:18}}>
        <View style={S.kidRow}>
          {kids.list.map(k=>{
            const n = countKnown(learn[k.id+'/'+lang]||{}, pack.categories).have;
            return (<Pressable key={k.id} style={[S.kidC, k.id===kids.cur&&{backgroundColor:'#fff'}]}
              onPress={()=>{sfx('tap'); const nk={...kids,cur:k.id}; setKids(nk); save('ws.kids',nk); setSession(null);}}>
              <Text style={{fontSize:42}}>{k.art}</Text>
              <Text style={[S.small, k.id===kids.cur&&{color:'#16233F'}]}>{n} words</Text></Pressable>);
          })}
          {kids.list.length<4 && <Pressable style={S.kidC} onPress={()=>{
            sfx('tap'); const used=kids.list.map(k=>k.art); const art=KID_ART.find(a=>used.indexOf(a)<0)||'🐥';
            const id='k'+Date.now(); const nk={list:kids.list.concat([{id,art}]),cur:id}; setKids(nk); save('ws.kids',nk);
          }}><Text style={{fontSize:42}}>＋</Text></Pressable>}
        </View>
        <View style={S.card}><Text style={S.small}>Each child keeps their own words, stickers and level. The app
        chooses what to teach next from what that child already knows.</Text></View>
      </ScrollView>
    </SafeAreaView>
  );

  /* ================= COLLECTION ================= */
  if (screen === 'collection') return (
    <SafeAreaView style={S.wrap}>
      <View style={S.head}><Pressable style={S.icon} onPress={()=>setScreen('home')}><Text style={{fontSize:19}}>←</Text></Pressable>
        <Text style={S.headT}>My Stickers</Text><View style={{flex:1}}/>
        <View style={[S.chip,{backgroundColor:T.sun}]}><Text style={S.chipD}>{counts.have}/{counts.all}</Text></View></View>
      <ScrollView contentContainerStyle={{padding:16}}>
        {pack.categories.map(c=>{
          const have = c.words.filter(w=>isKnown(bank(),w.key)).length;
          return (<View key={c.id} style={S.group}>
            <View style={S.groupTop}><Text style={{fontSize:19}}>{c.icon}</Text><Text style={S.groupN}>{c.native}</Text>
              <View style={{flex:1}}/><Text style={[S.small,{color:T.sun}]}>{have}/{c.words.length}</Text></View>
            <View style={S.cells}>
              {c.words.map(w=>{ const has = isKnown(bank(), w.key);
                return (<Pressable key={w.key} disabled={!has} style={[S.cell, has&&{backgroundColor:'#fff',borderWidth:0}]}
                  onPress={()=>{ say(w); sfx('twinkle'); }}>
                  {has ? <Art w={w} size={24}/> : <Text style={{color:'rgba(255,255,255,0.35)',fontSize:19}}>?</Text>}
                </Pressable>);
              })}
            </View></View>);
        })}
      </ScrollView>
    </SafeAreaView>
  );

  /* ================= PARENT ================= */
  if (screen === 'parent') return (
    <SafeAreaView style={S.wrap}>
      <View style={S.head}><Pressable style={S.icon} onPress={()=>setScreen('home')}><Text style={{fontSize:19}}>←</Text></Pressable>
        <Text style={S.headT}>For grown-ups</Text></View>
      <ScrollView contentContainerStyle={{padding:18}}>
        <View style={S.card}><Text style={S.cardT}>{pack.englishName} progress</Text>
          <Text style={S.small}>{counts.solid} solid · {counts.have} of {counts.all} met · {meta.sessions||0} sessions</Text></View>
        <Pressable style={[S.card,{backgroundColor:T.mint}]} onPress={()=>setScreen('record')}>
          <Text style={[S.cardT,{color:'#16233F'}]}>🎙  Record your own voice</Text>
          <Text style={[S.small,{color:'rgba(0,0,0,0.6)'}]}>{Object.keys(clips).filter(k=>k.indexOf(pack.code+':')===0).length} recorded</Text></Pressable>
        <View style={S.card}>
          <Text style={S.cardT}>Voice</Text>
          <Text style={S.small}>Tap a voice to hear it, then pick the one you like. ⭐ marks higher-quality voices.</Text>
          <Pressable style={[S.vRow, !meta.voice && S.vOn]} onPress={()=>{ setM({...meta, voice: null}); }}>
            <Text style={[S.vName, !meta.voice && {color:'#16233F'}]}>{!meta.voice ? '✓ ' : ''}Best available</Text>
          </Pressable>
          {voicesFor(pack.locale).slice(0,6).map(v=>{
            const on = meta.voice === v.identifier;
            const star = /enhanced|premium|neural/i.test(String(v.quality)+String(v.name)) ? ' ⭐' : '';
            return (
              <View key={v.identifier} style={{flexDirection:'row',alignItems:'center',gap:8}}>
                <Pressable style={[S.vRow,{flex:1}, on && S.vOn]} onPress={()=>setM({...meta, voice: v.identifier})}>
                  <Text style={[S.vName, on && {color:'#16233F'}]} numberOfLines={1}>{on?'✓ ':''}{v.name}{star}</Text>
                </Pressable>
                <Pressable style={S.icon} onPress={()=>{ try{ Speech.stop(); Speech.speak(
                    pack.categories[0].words[0].w, { language: pack.locale, voice: v.identifier, rate: 0.85 }); }catch(e){} }}>
                  <Text style={{fontSize:16}}>🔊</Text></Pressable>
              </View>
            );
          })}
          {voicesFor(pack.locale).length === 0 && <Text style={S.small}>No {pack.englishName} voice found on this device.</Text>}
          <Text style={[S.small,{marginTop:10,paddingTop:10,borderTopWidth:1,borderTopColor:'rgba(255,255,255,0.12)'}]}>
            For a much better voice: iPhone <Text style={{color:'#fff'}}>Settings → Accessibility → Spoken Content →
            Voices</Text>, choose the language and download an <Text style={{color:'#fff'}}>Enhanced</Text> or
            <Text style={{color:'#fff'}}> Premium</Text> voice. It is free and the app will use it automatically.
          </Text>
        </View>
        <View style={S.card}><Text style={S.cardT}>Games unlocked</Text>
          {LEVELS.map((l,i)=>(<View key={l.game} style={[S.lRow,{opacity:i<=lv.idx?1:0.45}]}>
            <Text style={{fontSize:17}}>{i<=lv.idx?l.icon:'🔒'}</Text><Text style={S.lName}>{l.name}</Text>
            <View style={{flex:1}}/><Text style={S.small}>{i<=lv.idx?'unlocked':l.at+' words'}</Text></View>))}
          {lv.next && <Text style={[S.small,{marginTop:8}]}>{lv.toNext} more until {lv.next.name}</Text>}</View>
        <View style={S.card}><Text style={S.cardT}>How this works</Text>
          <Text style={S.small}>Harder words come back more often and keep returning until met enough times to
          stick. Sessions are short and always finish. No streaks, no notifications, nothing collected.</Text></View>
      </ScrollView>
    </SafeAreaView>
  );

  /* ================= RECORD ================= */
  if (screen === 'record') {
    const all = []; pack.categories.forEach(c=>c.words.forEach(w=>all.push({w,c})));
    const idx = Math.min(meta.recIdx||0, all.length-1);
    const it = all[idx];
    const id = pack.code + ':' + it.w.key;
    const done = !!clips[id];
    return (
      <SafeAreaView style={S.wrap}>
        <View style={S.head}><Pressable style={S.icon} onPress={()=>setScreen('parent')}><Text style={{fontSize:19}}>←</Text></Pressable>
          <Text style={S.headT}>Record your voice</Text><View style={{flex:1}}/>
          <View style={S.chip}><Text style={S.chipT}>{Object.keys(clips).filter(k=>k.indexOf(pack.code+':')===0).length}/{all.length}</Text></View></View>
        <ScrollView contentContainerStyle={{padding:18,alignItems:'center'}}>
          <Text style={S.small}>{idx+1} of {all.length} · {it.c.native}</Text>
          <View style={{marginVertical:14}}><Art w={it.w} size={64}/></View>
          <Text style={S.bigWord}>{it.w.w}</Text>
          <Text style={S.small}>say this in {pack.englishName}</Text>
          <Pressable style={[S.recB,{backgroundColor: recOn ? '#E23B3B' : (done ? T.mint : T.coral)}]}
            onPress={async ()=>{
              try {
                if (recOn) {
                  await recorder.stop(); setRecOn(false);
                  const uri = recorder.uri;
                  if (uri) { const nc = {...clips, [id]:uri}; setClips(nc); save('ws.clips',nc); sfx('correct');
                             setTimeout(()=>setM({...meta, recIdx: Math.min(all.length-1, idx+1)}), 350); }
                } else {
                  const perm = await AudioModule.requestRecordingPermissionsAsync();
                  if (!perm.granted) { Alert.alert('Microphone needed','Allow microphone access in Settings.'); return; }
                  await setAudioModeAsync({ playsInSilentMode:true, allowsRecording:true });
                  await recorder.prepareToRecordAsync(); recorder.record(); setRecOn(true);
                }
              } catch(e) { Alert.alert('Recording problem', String(e && e.message ? e.message : e)); setRecOn(false); }
            }}>
            <Text style={{fontSize:38}}>{recOn?'⏹':'🎙'}</Text></Pressable>
          <Text style={S.small}>{recOn?'listening… tap to stop':done?'recorded ✓ — tap to redo':'tap to record'}</Text>
          <View style={{flexDirection:'row',gap:12,marginTop:16}}>
            <Pressable style={S.icon} onPress={()=>setM({...meta,recIdx:Math.max(0,idx-1)})}><Text style={{fontSize:17}}>←</Text></Pressable>
            <Pressable style={S.icon} onPress={()=>say(it.w)}><Text style={{fontSize:17}}>🔊</Text></Pressable>
            <Pressable style={S.icon} onPress={()=>setM({...meta,recIdx:Math.min(all.length-1,idx+1)})}><Text style={{fontSize:17}}>→</Text></Pressable>
          </View>
          <View style={[S.card,{marginTop:20}]}><Text style={S.small}>Your recordings replace the computer voice
          for those words. Record as few or as many as you like. Everything stays on this device.</Text></View>
        </ScrollView>
      </SafeAreaView>
    );
  }
  return null;
}

